-- Liabilities cell (liabilities), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA liabilities;

CREATE FUNCTION liabilities.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE liabilities.liabilitys (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    liability_type           text NOT NULL CHECK (liability_type IN ('loan', 'credit', 'tax', 'payable', 'subscription', 'other')),
    owner_scope              text NOT NULL DEFAULT 'personal' CHECK (owner_scope IN ('personal', 'solo_empire', 'venture', 'client', 'shared')),
    account_id               bigint,
    principal_amount         double precision CHECK (principal_amount IS NULL OR (principal_amount >= 0)),
    outstanding_amount       double precision CHECK (outstanding_amount IS NULL OR (outstanding_amount >= 0)),
    minimum_payment          double precision CHECK (minimum_payment IS NULL OR (minimum_payment >= 0)),
    interest_rate_percent    double precision CHECK (interest_rate_percent IS NULL OR (interest_rate_percent >= 0)),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    due_date                 date,
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('planned', 'active', 'overdue', 'settled', 'cancelled')),
    metadata                 jsonb CHECK (metadata IS NULL OR (jsonb_typeof(metadata) = 'object')),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX liabilitys_legacy ON liabilities.liabilitys (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX liabilitys_liability_type ON liabilities.liabilitys (workspace_id, liability_type);
CREATE INDEX liabilitys_owner_scope ON liabilities.liabilitys (workspace_id, owner_scope);
CREATE INDEX liabilitys_status ON liabilities.liabilitys (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE liabilities.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('liability')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE liabilities.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON liabilities.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['liabilitys', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE liabilities.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE liabilities.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON liabilities.%I'
                       ' USING (workspace_id = liabilities.current_workspace())'
                       ' WITH CHECK (workspace_id = liabilities.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA liabilities TO liabilities_api;
GRANT EXECUTE ON FUNCTION liabilities.current_workspace() TO liabilities_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON liabilities.liabilitys TO liabilities_api;
GRANT USAGE ON SEQUENCE liabilities.liabilitys_id_seq TO liabilities_api;
GRANT SELECT, INSERT ON liabilities.create_keys TO liabilities_api;
GRANT SELECT, INSERT ON liabilities.outbox TO liabilities_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON liabilities.outbox TO liabilities_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON liabilities.outbox TO liabilities_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA liabilities TO liabilities_publisher;
GRANT SELECT ON liabilities.outbox TO liabilities_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON liabilities.outbox TO liabilities_publisher;
